#include <iostream>
#include <locale>
#include <deque>

int main() {
    std::deque<char> p;
    std::deque<long> q;

    std::cout.imbue(std::locale("en_US.UTF-8"));
    std::cout << std::uppercase << "p.max_size() = " << std::dec << p.max_size()
              << " = 0x" << std::hex << p.max_size() << '\n'
              << "q.max_size() = " << std::dec << q.max_size() << " = 0x" << std::hex
              << q.max_size() << '\n';
}
